package io.github.windyzhu3.ontologylaw.api;
import static org.junit.jupiter.api.Assertions.*;import static io.github.windyzhu3.ontologylaw.execution.internal.persistence.CapabilityRoleExecutor.*;
import io.github.windyzhu3.ontologylaw.execution.*;import io.github.windyzhu3.ontologylaw.identity.AuthorizationService.*;import io.github.windyzhu3.ontologylaw.lead.ContactFlowFixture;import io.github.windyzhu3.ontologylaw.opportunity.*;import io.github.windyzhu3.ontologylaw.responsibility.*;import io.github.windyzhu3.ontologylaw.audit.AuditAppender;
import java.util.*;import java.time.*;import java.sql.*;import javax.crypto.spec.SecretKeySpec;import org.junit.jupiter.api.Test;
class R2CustomerRequirementsIT extends ContactFlowFixture {
 final OpportunityProgressProtection cipher=OpportunityProgressProtection.aesGcm(t->new SecretKeySpec(new byte[32],"AES"));Subject opportunity;
 void setup(boolean permission,boolean waiting)throws Exception{setupContact();var contact=execute(prepare(contact("CONNECTED_VALID")));try(var c=database.apiConnection()){opportunity=inTransaction(c,Capability.COMMAND,x->{grant(x,"SALES_OPPORTUNITY_OWNER");if(permission)grant(x,"CUSTOMER_REQUIREMENTS_MANAGE");var o=EventOpportunityReader.databaseBacked().forContact(x,seed.tenant(),contact.resultFact().id()).selector();if(waiting){var task=TaskFactory.databaseBacked().createInitialOpportunity(x,seed.tenant(),seed.appointment(),o,ZoneId.of("Asia/Shanghai"),businessAt);R2OpportunityProgressServices.create(cipher).record(x,seed.request().actor(),o,task.selector(),new OpportunityProgressInput("PHONE_CONNECTED","下周联系",businessAt,Instant.now().plusSeconds(86400).truncatedTo(java.time.temporal.ChronoUnit.MICROS)),ZoneId.of("Asia/Shanghai"),businessAt.plusSeconds(60));}return o;});}runtime=R2OpportunityCommandRuntime.fromSourcePolicy(policies,protection,cipher,null,"T05_IT");}
 Map<String,Object> doc(){return new LinkedHashMap<>(Map.of("participants",List.of(Map.of("role","CLIENT","newParty",Map.of("kind","ORGANIZATION","name","同名客户","distinctIdentityConfirmed",true))),"unknownOpponent",true,"matterName","销售洽谈事项","customerGoal","客户目标保密","serviceScope","提供咨询","knownConstraints","暂未提供完整材料","contactName","联系人甲","contactPhone","13800000000"));}
 CommandEnvelope command(boolean confirm,Subject draft,Subject previous,Map<String,Object> d){var p=new TreeMap<String,Object>();p.put("opportunityId",opportunity.id().toString());p.put("expectedOpportunityRevision",opportunity.revision());p.put("responsibilityBasis",R2CustomerRequirementsServices.selector(opportunity));p.put("expectedDraft",R2CustomerRequirementsServices.selector(draft));p.put("expectedConfirmation",R2CustomerRequirementsServices.selector(previous));if(!confirm)p.put("document",d);return new CommandEnvelope(confirm?CommandEnvelope.Type.CONFIRM_OPPORTUNITY_CUSTOMER_REQUIREMENTS:CommandEnvelope.Type.SAVE_OPPORTUNITY_CUSTOMER_DRAFT,UUID.randomUUID(),UUID.randomUUID(),seed.request().actor(),p);}
 CommandOutcome save(Map<String,Object> d)throws Exception{return execute(command(false,null,null,d));}
 Map<String,Object> read()throws Exception{try(var c=database.apiConnection()){return new R2CustomerRequirementsReadService(new byte[32],protection,cipher,AuditAppender.databaseBacked("T05_READ_IT")).read(c,seed.request().actor(),opportunity.id(),null,false);}}
 @Test void draft_is_encrypted_and_does_not_create_party_or_task()throws Exception{setup(true,false);var saved=save(doc());assertEquals(CommandOutcome.Status.SUCCEEDED,saved.status(),saved.rejectionCode());assertEquals("0",scalar("select count(*) from party.party where tenant_id=?",seed.tenant()));assertEquals("0",scalar("select count(*) from responsibility.task_occurrence where tenant_id=? and subject_id=?",seed.tenant(),opportunity.id()));assertEquals("0",scalar("select count(*) from audit.audit_entry_classified_v where tenant_id=? and change_summary::text like '%13800000000%'",seed.tenant()));assertTrue(read().containsKey("draft"));assertFalse(read().containsKey("confirmation"));}
 @Test void atomic_confirmation_creates_exact_identity_and_preserves_waiting()throws Exception{setup(true,true);var before=scalar("select task_occurrence_id::text||':'||revision||':'||state||':'||original_sla_due_at::text from responsibility.task_occurrence where tenant_id=? and subject_id=?",seed.tenant(),opportunity.id());var saved=save(doc());var e=command(true,saved.resultFact(),null,null);var result=execute(e);assertEquals(CommandOutcome.Status.SUCCEEDED,result.status(),result.rejectionCode());assertEquals(before,scalar("select task_occurrence_id::text||':'||revision||':'||state||':'||original_sla_due_at::text from responsibility.task_occurrence where tenant_id=? and subject_id=?",seed.tenant(),opportunity.id()));assertEquals("1",scalar("select count(*) from opportunity.customer_requirement_participant where tenant_id=? and role='CLIENT'",seed.tenant()));assertEquals(result,execute(e));try(var c=database.apiConnection()){assertEquals(200,new CommandReceiptRecoveryService(policies,protection,null,"T05_RECOVERY").read(c,seed.request().actor(),e.commandId(),UUID.randomUUID()).status());}assertTrue(read().containsKey("confirmation"));assertThrows(Exception.class,()->mutate("update opportunity.customer_requirement_confirmation set body_digest=body_digest where tenant_id=?",seed.tenant()));}
 @Test void required_fields_only_block_confirmation_and_contacts_do_not_form_client()throws Exception{setup(true,false);var d=doc();d.put("participants",List.of());var saved=save(d);assertEquals(CommandOutcome.Status.SUCCEEDED,saved.status());var result=execute(command(true,saved.resultFact(),null,null));assertEquals(CommandOutcome.Status.REJECTED,result.status());assertEquals("VALIDATION_FAILED",result.rejectionCode());assertEquals("0",scalar("select count(*) from party.party where tenant_id=?",seed.tenant()));}
 @Test void stale_draft_and_concurrent_first_save_never_fork()throws Exception{setup(true,false);var one=command(false,null,null,doc());var two=command(false,null,null,doc());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var results=pool.invokeAll(List.<java.util.concurrent.Callable<CommandOutcome>>of(()->execute(one),()->execute(two)));long success=0;for(var f:results)if(f.get().status()==CommandOutcome.Status.SUCCEEDED)success++;assertEquals(1,success);}assertEquals("1",scalar("select count(*) from opportunity.customer_requirement_draft where tenant_id=?",seed.tenant()));}
 @Test void grants_do_not_follow_from_ordinary_progress_and_revocation_blocks_receipt()throws Exception{setup(false,false);try(var c=database.apiConnection()){assertThrows(CommandHandler.Rejected.class,()->runtime.execute(c,command(false,null,null,doc())));}try(var c=database.apiConnection()){inTransaction(c,Capability.COMMAND,x->{grant(x,"CUSTOMER_REQUIREMENTS_MANAGE");return null;});}var e=command(false,null,null,doc());assertEquals(CommandOutcome.Status.SUCCEEDED,execute(e).status());mutate("update identity.authority_grant set state='REVOKED',revoked_at=clock_timestamp(),revocation_reason_code='FIXTURE',revision=revision+1 where tenant_id=? and authority_code='CUSTOMER_REQUIREMENTS_MANAGE'",seed.tenant());try(var c=database.apiConnection()){assertEquals(403,new CommandReceiptRecoveryService(policies,protection,null,"T05_REVOKED").read(c,seed.request().actor(),e.commandId(),UUID.randomUUID()).status());}}
 @Test void disclosure_audit_failure_returns_no_body()throws Exception{setup(true,false);save(doc());var fail=new AuditAppender(){public void append(Connection c,Entry e)throws SQLException{throw new SQLException("injected");}public void append(Connection c,CustomerRequirementsDisclosureEntry e)throws SQLException{throw new SQLException("injected");}};try(var c=database.apiConnection()){assertThrows(SQLException.class,()->new R2CustomerRequirementsReadService(new byte[32],protection,cipher,fail).read(c,seed.request().actor(),opportunity.id(),null,false));}}
 @Test void ciphertext_domains_cannot_be_substituted(){var t=UUID.randomUUID();var o=UUID.randomUUID();var f=UUID.randomUUID();var b=cipher.encryptCustomerRequirements(t,o,f,true,"secret");assertThrows(IllegalArgumentException.class,()->cipher.decryptCustomerRequirements(t,o,f,false,b));assertThrows(IllegalArgumentException.class,()->cipher.decrypt(t,o,f,b));}
 @SuppressWarnings("unchecked") Map<String,Object> canonical(Subject fact)throws Exception{try(var c=database.apiConnection()){return inTransaction(c,Capability.QUERY,x->new LinkedHashMap<>(R2CustomerRequirementsServices.create(cipher).read(x,seed.tenant(),fact).document()));}}
 @SuppressWarnings("unchecked") Subject client(Map<String,Object> document){var p=(Map<String,Object>)((List<?>)document.get("participants")).getFirst();return R2CustomerRequirementsServices.selected(p);}
 @Test void subsequent_revision_reuses_identity_and_empty_known_limits_are_allowed()throws Exception{setup(true,false);var d=doc();d.put("knownConstraints","");var first=save(d);var confirmed=execute(command(true,first.resultFact(),null,null));assertEquals(CommandOutcome.Status.SUCCEEDED,confirmed.status(),confirmed.rejectionCode());assertEquals(true,read().get("draftConsumed"));var canonical=canonical(confirmed.resultFact());var exact=client(canonical);canonical.put("customerGoal","修订后的客户目标");var second=execute(command(false,first.resultFact(),confirmed.resultFact(),canonical));var revised=execute(command(true,second.resultFact(),confirmed.resultFact(),null));assertEquals(CommandOutcome.Status.SUCCEEDED,revised.status(),revised.rejectionCode());assertEquals(exact,client(canonical(revised.resultFact())));assertEquals("1",scalar("select count(*) from party.party where tenant_id=?",seed.tenant()));assertEquals("2",scalar("select count(*) from opportunity.customer_requirement_confirmation where tenant_id=?",seed.tenant()));}
 @SuppressWarnings("unchecked") @Test void shared_profile_change_requires_separate_grant_and_is_atomic_with_confirmation()throws Exception{setup(true,false);var first=save(doc());var confirmed=execute(command(true,first.resultFact(),null,null));var changed=canonical(confirmed.resultFact());var exact=client(changed);var p=new LinkedHashMap<String,Object>((Map<String,Object>)((List<?>)changed.get("participants")).getFirst());p.put("profileChange",Map.of("name","规范名称修订","sharedProfileImpactConfirmed",true));changed.put("participants",List.of(p));var second=execute(command(false,first.resultFact(),confirmed.resultFact(),changed));var denied=execute(command(true,second.resultFact(),confirmed.resultFact(),null));assertEquals(CommandOutcome.Status.REJECTED,denied.status());assertEquals("NOT_AUTHORIZED",denied.rejectionCode());assertEquals("同名客户",scalar("select canonical_name from party.party where tenant_id=? and party_id=?",seed.tenant(),exact.id()));assertEquals("1",scalar("select count(*) from opportunity.customer_requirement_confirmation where tenant_id=?",seed.tenant()));try(var c=database.apiConnection()){inTransaction(c,Capability.COMMAND,x->{grant(x,"PARTY_PROFILE_MANAGE");return null;});}var revised=execute(command(true,second.resultFact(),confirmed.resultFact(),null));assertEquals(CommandOutcome.Status.SUCCEEDED,revised.status(),revised.rejectionCode());assertEquals(exact.revision()+1,client(canonical(revised.resultFact())).revision());try(var c=database.apiConnection()){inTransaction(c,Capability.QUERY,x->{var old=R2CustomerRequirementsServices.create(cipher).read(x,seed.tenant(),confirmed.resultFact());assertEquals("同名客户",old.partySnapshots().getFirst().name());return null;});}}
 @Test void changed_party_version_requires_fresh_read_and_never_silently_rebinds()throws Exception{setup(true,false);var first=save(doc());var confirmed=execute(command(true,first.resultFact(),null,null));var canonical=canonical(confirmed.resultFact());var exact=client(canonical);var second=execute(command(false,first.resultFact(),confirmed.resultFact(),canonical));mutate("update party.party set canonical_name='外部资料修订',revision=revision+1 where tenant_id=? and party_id=?",seed.tenant(),exact.id());var stale=execute(command(true,second.resultFact(),confirmed.resultFact(),null));assertEquals(CommandOutcome.Status.REJECTED,stale.status());assertEquals("STALE_SUBJECT",stale.rejectionCode());assertEquals("1",scalar("select count(*) from opportunity.customer_requirement_confirmation where tenant_id=?",seed.tenant()));}
 @Test void closure_prevents_draft_save_and_preserves_existing_draft()throws Exception{setup(true,false);var first=save(doc());try(var c=database.apiConnection()){inTransaction(c,Capability.COMMAND,x->{var service=R2OpportunityClosureServices.create(cipher);var state=service.inspect(x,seed.tenant(),opportunity.id());service.close(x,seed.tenant(),new OpportunityClosureService.Input(state.opportunity(),state.responsibility().basis(),state.task(),state.waitReceipt(),seed.appointment(),"OTHER","结束销售洽谈"));return null;});}var stale=execute(command(false,first.resultFact(),null,doc()));assertEquals(CommandOutcome.Status.REJECTED,stale.status());assertEquals("STALE_SUBJECT",stale.rejectionCode());assertEquals("1",scalar("select count(*) from opportunity.customer_requirement_draft where tenant_id=?",seed.tenant()));assertEquals(false,read().get("editable"));}
 @Test void selected_party_deny_revokes_draft_receipt_and_body()throws Exception{setup(true,false);var first=save(doc());var confirmed=execute(command(true,first.resultFact(),null,null));var canonical=canonical(confirmed.resultFact());var exact=client(canonical);var e=command(false,first.resultFact(),confirmed.resultFact(),canonical);assertEquals(CommandOutcome.Status.SUCCEEDED,execute(e).status());for(var code:List.of("CUSTOMER_REQUIREMENTS_MANAGE","SALES_OPPORTUNITY_OWNER"))mutate("insert into identity.object_access_grant(tenant_id,object_access_grant_id,grantee_principal_id,granted_by_appointment_id,access_code,effect_code,valid_from,state,created_at,object_subject_type,object_subject_id,object_subject_revision) values(?,?,?,?,?,'DENY',clock_timestamp()-interval '1 day','ACTIVE',clock_timestamp(),'party.party',?,?)",seed.tenant(),UUID.randomUUID(),seed.request().actor().principalId(),seed.appointment(),code,exact.id(),exact.revision());try(var c=database.apiConnection()){assertEquals(403,new CommandReceiptRecoveryService(policies,protection,null,"T05_PARTY_DENY").read(c,seed.request().actor(),e.commandId(),UUID.randomUUID()).status());}assertFalse(read().containsKey("draft"));assertFalse(read().containsKey("confirmation"));}

 @Test void command_audit_failure_rolls_back_party_confirmation_and_event_together()throws Exception{setup(true,false);var first=save(doc());var before=counts();var fail=new AuditAppender(){public void append(Connection c,Entry e)throws SQLException{throw new SQLException("injected command audit failure");}};var isolated=new CommandRuntime(List.of(new R2CustomerRequirementsCommand(CommandEnvelope.Type.CONFIRM_OPPORTUNITY_CUSTOMER_REQUIREMENTS,cipher)),io.github.windyzhu3.ontologylaw.identity.AuthorizationService.databaseBacked(),fail,R2OpportunityCommandRuntime.authorization(io.github.windyzhu3.ontologylaw.lead.R1AuthorizationReaders.databaseBacked(policies)),R2OpportunityCommandRuntime.events(io.github.windyzhu3.ontologylaw.lead.R1EventReaders.databaseBacked(),cipher));try(var c=database.apiConnection()){assertThrows(SQLException.class,()->isolated.execute(c,command(true,first.resultFact(),null,null)));}assertEquals("0",scalar("select count(*) from party.party where tenant_id=?",seed.tenant()));assertEquals("0",scalar("select count(*) from opportunity.customer_requirement_confirmation where tenant_id=?",seed.tenant()));assertEquals("0",scalar("select count(*) from execution.domain_event where tenant_id=? and event_type='OpportunityCustomerRequirementsConfirmedV1'",seed.tenant()));assertEquals(before,counts());}

 @Test void immutable_draft_sources_and_participant_set_cannot_be_extended_later()throws Exception{setup(true,false);var saved=save(doc());var confirmed=execute(command(true,saved.resultFact(),null,null));var exact=client(canonical(confirmed.resultFact()));var profile=UUID.fromString(scalar("select profile_version_id from party.profile_version where tenant_id=? and party_id=? and party_revision=?",seed.tenant(),exact.id(),exact.revision()));assertThrows(Exception.class,()->mutate("insert into opportunity.customer_requirement_participant(tenant_id,customer_requirement_participant_id,revision,confirmation_id,party_id,party_revision,role,profile_version_id) values(?,?,0,?,?,?,'OTHER',?)",seed.tenant(),UUID.randomUUID(),confirmed.resultFact().id(),exact.id(),exact.revision(),profile));assertThrows(Exception.class,()->mutate("insert into opportunity.customer_requirement_draft_party(tenant_id,customer_requirement_draft_party_id,revision,draft_id,party_id,party_revision) values(?,?,0,?,?,?)",seed.tenant(),UUID.randomUUID(),saved.resultFact().id(),exact.id(),exact.revision()));}

}
